/**
 * Argument parsing per the README.
 *
 * `--retry <n>` sets the retry count (default 0). `--retry` without a value,
 * or with a value that is not a non-negative integer, is an error. The
 * `--retry=<n>` form is also accepted, and the last occurrence wins.
 */
export function parseArgs(argv) {
  let retries = 0
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i]
    if (arg === '--retry') {
      const raw = argv[i + 1]
      if (raw === undefined) {
        throw new Error('--retry requires a value: --retry <n>')
      }
      retries = parseRetryCount(raw)
      i += 1
    } else if (arg.startsWith('--retry=')) {
      retries = parseRetryCount(arg.slice('--retry='.length))
    }
  }
  return { retries }
}

function parseRetryCount(raw) {
  if (!/^\d+$/.test(raw)) {
    throw new Error(`invalid --retry value: ${JSON.stringify(raw)} (expected a non-negative integer)`)
  }
  return Number(raw)
}

/**
 * Retry logic per the README.
 *
 * Calls `fn()` and, when it rejects with a transient error
 * (`code === 'ETIMEDOUT'` or `'ECONNRESET'`), retries up to `retries` times.
 * Each retry waits a short positive delay with exponential backoff
 * (default base 25ms, capped at 1s); pass `{ delayMs }` to override for tests.
 * Non-transient errors propagate immediately, and when retries are exhausted
 * the last error is rethrown.
 */
const TRANSIENT_CODES = new Set(['ETIMEDOUT', 'ECONNRESET'])
const DEFAULT_DELAY_MS = 25
const MAX_DELAY_MS = 1000

export async function retryWithBackoff(fn, retries, { delayMs = DEFAULT_DELAY_MS } = {}) {
  let attempt = 0
  let lastError
  while (attempt <= retries) {
    try {
      return await fn()
    } catch (error) {
      lastError = error
      if (!isTransient(error) || attempt === retries) {
        throw error
      }
      await sleep(Math.min(delayMs * 2 ** attempt, MAX_DELAY_MS))
      attempt += 1
    }
  }
  throw lastError
}

function isTransient(error) {
  return error != null && TRANSIENT_CODES.has(error.code)
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { parseArgs } from '../src/args.js'

test('args: default retries is 0', () => {
  assert.deepEqual(parseArgs(['run']), { retries: 0 })
})

test('args: default retries is 0 with no arguments', () => {
  assert.deepEqual(parseArgs([]), { retries: 0 })
})

test('args: --retry <n> sets the count', () => {
  assert.deepEqual(parseArgs(['run', '--retry', '3']), { retries: 3 })
})

test('args: --retry 0 is accepted', () => {
  assert.deepEqual(parseArgs(['run', '--retry', '0']), { retries: 0 })
})

test('args: --retry=<n> form is accepted', () => {
  assert.deepEqual(parseArgs(['run', '--retry=3']), { retries: 3 })
})

test('args: the last --retry wins', () => {
  assert.deepEqual(parseArgs(['--retry', '2', '--retry', '5']), { retries: 5 })
})

test('args: --retry without value is an error', () => {
  assert.throws(() => parseArgs(['run', '--retry']))
  assert.throws(() => parseArgs(['--retry']))
  assert.throws(() => parseArgs(['--retry=']))
})

test('args: --retry with a non-integer value is an error', () => {
  assert.throws(() => parseArgs(['--retry', 'abc']))
  assert.throws(() => parseArgs(['--retry', '1.5']))
  assert.throws(() => parseArgs(['--retry', '']))
  assert.throws(() => parseArgs(['--retry', '--retry']))
})

test('args: --retry with a negative value is an error', () => {
  assert.throws(() => parseArgs(['--retry', '-1']))
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { retryWithBackoff } from '../src/retry.js'

const transient = (message = 'transient', code = 'ETIMEDOUT') => {
  const error = new Error(message)
  error.code = code
  return error
}

test('retry: succeeds on the first call', async () => {
  const result = await retryWithBackoff(() => Promise.resolve('ok'), 3)
  assert.equal(result, 'ok')
})

test('retry: retries a transient failure then succeeds', async () => {
  let calls = 0
  const result = await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) return Promise.reject(transient('timeout'))
    return Promise.resolve('ok')
  }, 3)
  assert.equal(result, 'ok')
  assert.equal(calls, 2)
})

test('retry: gives up after retries are exhausted and rethrows the last error', async () => {
  let calls = 0
  await assert.rejects(
    () =>
      retryWithBackoff(() => {
        calls += 1
        return Promise.reject(transient('timeout'))
      }, 2),
    { code: 'ETIMEDOUT' }
  )
  assert.equal(calls, 3) // 1 initial call + 2 retries
})

test('retry: retries ECONNRESET as transient', async () => {
  let calls = 0
  const result = await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) return Promise.reject(transient('reset', 'ECONNRESET'))
    return Promise.resolve('ok')
  }, 2)
  assert.equal(result, 'ok')
  assert.equal(calls, 2)
})

test('retry: does not retry non-transient errors', async () => {
  let calls = 0
  const error = new Error('forbidden')
  error.code = 'EACCES'
  await assert.rejects(
    () =>
      retryWithBackoff(() => {
        calls += 1
        return Promise.reject(error)
      }, 3),
    { code: 'EACCES' }
  )
  assert.equal(calls, 1)
})

test('retry: errors without a code are not retried', async () => {
  let calls = 0
  await assert.rejects(
    () =>
      retryWithBackoff(() => {
        calls += 1
        return Promise.reject(new Error('plain'))
      }, 3),
    /plain/
  )
  assert.equal(calls, 1)
})

test('retry: retries=0 never retries', async () => {
  let calls = 0
  await assert.rejects(
    () =>
      retryWithBackoff(() => {
        calls += 1
        return Promise.reject(transient('timeout'))
      }, 0),
    { code: 'ETIMEDOUT' }
  )
  assert.equal(calls, 1)
})

test('retry: a synchronous throw is retried like a rejection', async () => {
  let calls = 0
  const result = await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) throw transient('timeout')
    return 'ok'
  }, 2)
  assert.equal(result, 'ok')
  assert.equal(calls, 2)
})

test('retry: waits a positive delay between attempts', async () => {
  let calls = 0
  const delayMs = 40
  const start = Date.now()
  await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) return Promise.reject(transient('timeout'))
    return Promise.resolve('ok')
  }, 1, { delayMs })
  const elapsed = Date.now() - start
  assert.ok(elapsed >= delayMs, `elapsed ${elapsed}ms is less than delay ${delayMs}ms`)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { parseArgs } from '../src/args.js'
import { retryWithBackoff } from '../src/retry.js'

/**
 * Deterministic PRNG (mulberry32) so the 30% packet-loss simulation is fully
 * reproducible and the >= 99% success-rate assertion never flakes.
 */
function mulberry32(seed) {
  return function next() {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const LOSS_RATE = 0.3 // 30% packet loss per attempt
const TRIALS = 2000 // runs of one logical request
const SEED = 0xc0ffee

test('acceptance: >= 99% success under 30% packet loss with --retry 3', async () => {
  const { retries } = parseArgs(['run', '--retry', '3'])
  const rand = mulberry32(SEED)
  let failures = 0

  for (let i = 0; i < TRIALS; i += 1) {
    try {
      await retryWithBackoff(async () => {
        if (rand() < LOSS_RATE) {
          const error = new Error('packet lost')
          error.code = 'ETIMEDOUT'
          throw error
        }
        return 'ok'
      }, retries, { delayMs: 0 })
    } catch {
      failures += 1
    }
  }

  const successRate = 1 - failures / TRIALS
  assert.ok(
    successRate >= 0.99,
    `success rate ${(successRate * 100).toFixed(2)}% < 99% (${failures}/${TRIALS} runs failed)`
  )
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { main } from '../src/cli.js'

test('cli: main prints the result and accepts --retry', async () => {
  const originalLog = console.log
  const logs = []
  console.log = (...args) => logs.push(args)
  try {
    await main(['run', '--retry', '3'])
  } finally {
    console.log = originalLog
  }
  assert.deepEqual(logs, [['ok']])
})

test('cli: main rejects on a malformed --retry', async () => {
  await assert.rejects(() => main(['run', '--retry']))
})

